import{_ as a,o as i,c as l,ag as t}from"./chunks/framework.CvZZEx4j.js";const u=JSON.parse('{"title":"Live2D 角色模型","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/live2d.md","filePath":"advanced/live2d.md","lastUpdated":null}'),o={name:"advanced/live2d.md"};function d(r,e,n,s,h,c){return i(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="live2d-角色模型" tabindex="-1">Live2D 角色模型 <a class="header-anchor" href="#live2d-角色模型" aria-label="Permalink to &quot;Live2D 角色模型&quot;">​</a></h1><h2 id="什么是-live2d" tabindex="-1">什么是 Live2D <a class="header-anchor" href="#什么是-live2d" aria-label="Permalink to &quot;什么是 Live2D&quot;">​</a></h2><p>Live2D 是一种让 2D 角色动起来的技术。插件支持直接在 Galgame 覆盖层中展示 Live2D 模型，让角色拥有呼吸、眨眼、表情变化等动态效果。</p><p>支持的模型格式：</p><ul><li>Cubism 2（旧版 <code>.moc</code> 格式）</li><li>Cubism 4（<code>.moc3</code> 格式）</li><li>Cubism 5（最新版 <code>.moc3</code> 格式）</li></ul><h2 id="添加-live2d-模型" tabindex="-1">添加 Live2D 模型 <a class="header-anchor" href="#添加-live2d-模型" aria-label="Permalink to &quot;添加 Live2D 模型&quot;">​</a></h2><h3 id="本地上传" tabindex="-1">本地上传 <a class="header-anchor" href="#本地上传" aria-label="Permalink to &quot;本地上传&quot;">​</a></h3><ol><li>打开 <strong>设置面板</strong> → <strong>Live2D 设置</strong></li><li>选择要绑定的角色名</li><li>点击 <strong>上传模型</strong></li><li>选择模型文件夹（包含 <code>.model3.json</code> 或 <code>.model.json</code>）</li></ol><h3 id="从远程-url-加载" tabindex="-1">从远程 URL 加载 <a class="header-anchor" href="#从远程-url-加载" aria-label="Permalink to &quot;从远程 URL 加载&quot;">​</a></h3><ol><li>在 Live2D 设置中选择角色</li><li>选择「远程」来源</li><li>填入模型的 <code>model3.json</code> 完整 URL</li><li>插件会自动下载并缓存模型</li></ol><h3 id="在线模型库" tabindex="-1">在线模型库 <a class="header-anchor" href="#在线模型库" aria-label="Permalink to &quot;在线模型库&quot;">​</a></h3><ol><li>在 Live2D 设置中点击 <strong>浏览在线模型库</strong></li><li>浏览可用的模型</li><li>点击即可导入</li></ol><h2 id="调整位置和缩放" tabindex="-1">调整位置和缩放 <a class="header-anchor" href="#调整位置和缩放" aria-label="Permalink to &quot;调整位置和缩放&quot;">​</a></h2><p>插件提供 <strong>可视化位置编辑器</strong>：</p><ol><li>在 Live2D 设置中点击 <strong>调整位置</strong></li><li>拖拽模型调整位置</li><li>使用缩放滑块调整大小</li><li>选择槽位（左 / 中 / 右）</li><li>确认保存</li></ol><h2 id="表情与动作" tabindex="-1">表情与动作 <a class="header-anchor" href="#表情与动作" aria-label="Permalink to &quot;表情与动作&quot;">​</a></h2><p>插件会将 AI 输出中的表情标签自动映射到 Live2D 模型的表情和动作：</p><table tabindex="0"><thead><tr><th>AI 输出表情</th><th>Live2D 行为</th></tr></thead><tbody><tr><td>微笑</td><td>切换到开心表情</td></tr><tr><td>生气</td><td>切换到生气表情</td></tr><tr><td>难过</td><td>切换到悲伤表情</td></tr><tr><td>...</td><td>自动匹配</td></tr></tbody></table><h2 id="口型同步" tabindex="-1">口型同步 <a class="header-anchor" href="#口型同步" aria-label="Permalink to &quot;口型同步&quot;">​</a></h2><p>当 TTS（语音合成）播放角色语音时，Live2D 模型可以同步移动嘴部：</p><ol><li>确保已启用 TTS</li><li>在 Live2D 设置中启用口型同步</li><li>角色说话时，模型的嘴巴会随音频同步运动</li></ol>',21)])])}const m=a(o,[["render",d]]);export{u as __pageData,m as default};
